/**
 * Workflow Discovery Handler
 */
import { registerWorkflow } from "../../workflow/registry.js";
export const workflowHandler = {
    typeName: "workflow",
    validate: (item) => item !== null &&
        typeof item === "object" &&
        "definition" in item &&
        "id" in item &&
        typeof item.id === "string",
    getId: (workflow) => workflow.id,
    register: (_id, workflow) => {
        registerWorkflow(workflow);
        return workflow;
    },
    getResultMap: (result) => result.workflows,
};
